"""Card replacement tools for Milestone 2 hybrid agent."""

from __future__ import annotations

# The tool loader puts the agent root on sys.path while importing this module,
# so shared code under lib/ is importable from any tool location.
from lib.wallet_loader import load_wallet_data

from rasa.mantle.tools.decorator import ToolContext, tool
from rasa.mantle.tools.result import ToolResult

_VALID_REASONS = frozenset({"lost", "stolen", "damaged", "not_received"})
_VALID_REPLACE_TARGETS = frozenset({"customer", "authorized_user", "both"})
_VALID_SHIPPING = frozenset({"rush", "standard"})
_VALID_WALLET_PROVIDERS = frozenset({"Apple Pay", "Google Pay", "Samsung Pay"})

_SHIPPING_SUMMARY = {
    "standard": "Standard (5 to 7 business days)",
    "rush": "Rush (1 to 2 business days)",
}

_WALLET_PROVIDERS_DOC = (
    "Valid selected_wallet_provider values (exact string, exactly one):\n"
    + "\n".join(f"  - {value}" for value in sorted(_VALID_WALLET_PROVIDERS))
)

_wallet = load_wallet_data()


def _card_for_session(context: ToolContext) -> tuple[str | None, dict | None]:
    card_id = context.memory.get("card_disambiguation.selected_card_id")
    if not card_id:
        return None, None
    card = _wallet.get_card(str(card_id))
    return str(card_id), card


@tool(
    description=(
        "Check whether the customer may use self-service card replacement "
        "(account level only; does not load cards)."
    )
)
async def check_account_replacement_eligibility(
    context: ToolContext = None,
) -> ToolResult:
    eligible = bool(getattr(_wallet, "ACCOUNT_SELF_SERVICE_REPLACE_ELIGIBLE", True))
    context.memory.set("account_replace_eligible", eligible)
    return ToolResult(llm_response={"account_eligible": eligible})


@tool(description="Memory validation tool: validate the replacement reason.")
async def run_after_setting_replacement_reason(
    context: ToolContext = None,
) -> ToolResult:
    reason = context.memory.get("replacement_reason")
    if reason not in _VALID_REASONS:
        return ToolResult(
            llm_response={
                "error": "invalid_reason",
                "valid_values": sorted(_VALID_REASONS),
            }
        )
    return ToolResult(llm_response={"replacement_reason": reason})


########################## DAMAGED CARD TOOLS ##########################


@tool(
    description=(
        "Memory validation tool: validate the replace target and mark "
        "damaged-card scope complete."
    )
)
async def run_after_setting_replace_target(context: ToolContext = None) -> ToolResult:
    replace_target = context.memory.get("replace_target")
    if replace_target not in _VALID_REPLACE_TARGETS:
        return ToolResult(
            llm_response={
                "error": "invalid_replace_target",
                "valid_values": sorted(_VALID_REPLACE_TARGETS),
            }
        )
    context.memory.set("damage_processed", True)
    count = 2 if replace_target == "both" else 1
    return ToolResult(llm_response={"ok": True, "damaged_replace_count": count})


@tool(
    description=(
        "Damaged path when the card has no authorized user: record customer-only "
        "replacement (flow automation, not an LLM setter)."
    )
)
async def apply_damaged_customer_replace(context: ToolContext = None) -> ToolResult:
    context.memory.set("replace_target", "customer")
    context.memory.set("damage_processed", True)
    return ToolResult(llm_response={"ok": True, "replace_target": "customer"})


@tool(
    description="Whether the selected card product has an authorized-user card on the account."
)
async def check_damaged_replacement_scope(context: ToolContext = None) -> ToolResult:
    _, card = _card_for_session(context)
    if card is None:
        return ToolResult(
            llm_response={"has_authorized_user": False, "error": "no_card_selected"}
        )
    has_au = bool(card.get("has_authorized_user", False))
    context.memory.set("has_authorized_user", has_au)
    return ToolResult(llm_response={"has_authorized_user": has_au})


########################## SHIPPING TOOLS ##########################


@tool(
    description=(
        "Shipping step only: whether rush delivery is available for the selected card. "
        "Call before offering rush vs standard. Do not call at card eligibility."
    )
)
async def check_rush_shipping_eligibility(context: ToolContext = None) -> ToolResult:
    _, card = _card_for_session(context)
    if card is None:
        return ToolResult(
            llm_response={"rush_eligible": False, "error": "no_card_selected"}
        )
    rush = bool(card["rush_eligible"])
    context.memory.set("rush_eligible", rush)
    return ToolResult(llm_response={"rush_eligible": rush})


@tool(
    description=(
        "Memory validation tool: validate rush shipping and sync order summary."
    )
)
async def run_after_setting_shipping_type(context: ToolContext = None) -> ToolResult:
    raw = context.memory.get("shipping_type")
    # Normalize casing/whitespace the removed set_shipping_type tool used to apply,
    # so benign variants ("Rush", " standard ") from set_fields still validate.
    shipping = raw.strip().lower() if isinstance(raw, str) else raw
    if shipping not in _VALID_SHIPPING:
        return ToolResult(
            llm_response={
                "error": "invalid_shipping_type",
                "valid_values": sorted(_VALID_SHIPPING),
            }
        )
    if shipping != raw:
        context.memory.set("shipping_type", shipping)
    if shipping == "rush":
        _, card = _card_for_session(context)
        rush_ok = bool(card["rush_eligible"]) if card else False
        context.memory.set("rush_eligible", rush_ok)
        if not rush_ok:
            return ToolResult(llm_response={"error": "rush_not_eligible"})
    context.memory.set("order_shipping_summary", _SHIPPING_SUMMARY[shipping])
    context.memory.set("order_confirmed", None)
    return ToolResult(llm_response={"ok": True, "shipping_type": shipping})


@tool(
    description="Place the replacement order after the customer explicitly confirmed the order summary with yes.",
)
async def process_card_replacement(context: ToolContext = None) -> ToolResult:
    shipping = context.memory.get("shipping_type")
    if shipping not in _VALID_SHIPPING:
        return ToolResult(
            llm_response={
                "ok": False,
                "error": "shipping_not_set",
                "hint": "Set shipping_type via set_fields when the customer chooses rush or standard.",
            }
        )
    context.memory.set("order_confirmed", True)
    context.memory.set("replacement_submitted", True)
    context.memory.set("order_shipping_summary", _SHIPPING_SUMMARY[shipping])
    return ToolResult(llm_response={"submitted": True, "shipping_type": shipping})


########################## FRAUD TRANSACTION TOOLS ##########################


@tool(description="Memory validation tool: mark transaction review complete.")
async def run_after_setting_all_charges_familiar(
    context: ToolContext = None,
) -> ToolResult:
    context.memory.set("transaction_review_complete", True)
    familiar = context.memory.get("all_charges_familiar")
    return ToolResult(llm_response={"ok": True, "all_charges_familiar": familiar})


@tool(
    description="Load recent transactions for the selected card (requires selected_card_id)."
)
async def check_number_of_transactions_returned(
    context: ToolContext = None,
) -> ToolResult:
    card_id = context.memory.get("card_disambiguation.selected_card_id")
    if not card_id:
        return ToolResult(
            llm_response={"transaction_available": False, "error": "no_card_selected"}
        )

    transactions = _wallet.transactions_for_card(str(card_id))
    card = _wallet.get_card(str(card_id))
    card_label = (
        card["label"]
        if card
        else context.memory.get("card_disambiguation.selected_card_label")
    )
    payload = _wallet.transaction_tool_result(transactions, card_label=card_label)

    context.memory.set("transaction_available", payload["transaction_available"])
    context.memory.set("recent_transactions", transactions)
    context.memory.set("recent_transactions_text", payload["transactions_display_text"])
    context.memory.set("recent_transactions_card_id", card_id)
    context.memory.set("recent_transactions_card_label", card_label)
    return ToolResult(llm_response=payload)


########################## LOCK TOOLS ##########################


@tool(
    description=(
        "Lock the card after the customer agreed to lock in this conversation "
        "(yes, please lock, go ahead) — including if they said so earlier; do not "
        "re-ask if they already agreed. Do not call without a clear yes."
    )
)
async def lock_card(context: ToolContext = None) -> ToolResult:
    context.memory.set("card_locked_this_flow", True)
    context.memory.set("lock_declined", False)
    return ToolResult(llm_response={"card_is_locked": True})


########################## DIGITAL WALLET TOOLS ##########################


@tool(
    description="Whether the selected card is eligible for digital wallet provisioning."
)
async def check_digital_wallet_eligibility_and_status(
    context: ToolContext = None,
) -> ToolResult:
    _, card = _card_for_session(context)
    if card is None:
        return ToolResult(
            llm_response={
                "digital_wallet_eligible": False,
                "card_already_provisioned": False,
                "error": "no_card_selected",
            }
        )
    dw = bool(card["digital_wallet_eligible"])
    provisioned = bool(card["already_provisioned"])
    context.memory.set("digital_wallet_eligible", dw)
    context.memory.set("card_already_provisioned", provisioned)
    return ToolResult(
        llm_response={
            "digital_wallet_eligible": dw,
            "card_already_provisioned": provisioned,
        }
    )


@tool(
    description=(
        "Memory validation tool: record wallet consent decline or acceptance "
        "intent."
    )
)
async def run_after_setting_accept(context: ToolContext = None) -> ToolResult:
    # accept is exposed skill-wide via set_fields, but the wallet decision is
    # only meaningful once the eligibility check has shown the card is eligible
    # and not already provisioned — i.e. the wallet offer is actually reachable.
    # Set before that, an early accept=false would write wallet_declined and make
    # route_wallet skip emit_wallet_offer. Reject so the premature write rolls back.
    if not context.memory.get("digital_wallet_eligible") or context.memory.get(
        "card_already_provisioned"
    ):
        return ToolResult(
            llm_response={
                "error": "wallet_offer_not_ready",
                "hint": (
                    "Do not set accept before the digital wallet offer has been "
                    "shown. Run check_digital_wallet_eligibility_and_status first."
                ),
            }
        )
    accept = context.memory.get("accept")
    context.memory.set("wallet_declined", not accept)
    return ToolResult(llm_response={"accept": accept, "wallet_declined": not accept})


@tool(
    description=(
        "Memory validation tool: validate wallet provider and provision the "
        "digital wallet.\n"
        + _WALLET_PROVIDERS_DOC
    )
)
async def run_after_setting_selected_wallet_provider(
    context: ToolContext = None,
) -> ToolResult:
    provider = (context.memory.get("selected_wallet_provider") or "").strip()
    if provider not in _VALID_WALLET_PROVIDERS:
        return ToolResult(
            llm_response={
                "error": "invalid_wallet_provider",
                "valid_values": sorted(_VALID_WALLET_PROVIDERS),
            }
        )
    if not context.memory.get("accept"):
        return ToolResult(
            llm_response={
                "error": "wallet_not_accepted",
                "hint": (
                    "Confirm the digital wallet offer (set accept via set_fields) "
                    "before choosing a provider."
                ),
            }
        )
    # The removed record_digital_wallet_consent tool refused provisioning when
    # the card was ineligible or already provisioned; keep that guard so a
    # skill-wide set_fields write can't provision a card that never qualified.
    if not context.memory.get("digital_wallet_eligible") or context.memory.get(
        "card_already_provisioned"
    ):
        return ToolResult(
            llm_response={
                "error": "wallet_not_provisionable",
                "hint": (
                    "The selected card is not eligible for digital wallet "
                    "provisioning or is already provisioned; do not provision it."
                ),
            }
        )
    context.memory.set("digital_wallet_provisioned", True)
    context.memory.set("wallet_declined", False)
    return ToolResult(
        llm_response={
            "digital_wallet_provisioned": True,
            "selected_wallet_provider": provider,
        }
    )
